<script setup>
import { computed, ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
import B from '../Components/SynauxButton.vue';
import F from '../Components/SynauxField.vue';
import T from '../Components/SynauxTitle.vue';
import S from '../Components/SynauxStatus.vue';
import E from '../Components/SynauxEmpty.vue';
import ClientScreens from './ClientScreens.vue';
import { money, date, useSubmit } from '../support/synaux';
// Gestión reutiliza las lecturas, mientras cada edición vuelve a verificar el emisor en Laravel.
const props = defineProps({data:Object});
const submit = useSubmit();
const section = computed(() => props.data.section || 'resumen');
const selected = props.data.selected ?? {};
const query = ref('');
const status = ref('');
const preview = ref(false);
const project = ref(null);
const adminModal = ref(false);
const admin = computed(() => props.data.administration ?? {services:[],categories:[],questions:[],components:[],rules:[],tariffs:[]});
const resources = {servicios:'services',preguntas:'questions',componentes:'components',reglas:'rules',tarifario:'tariffs'};
const adminRows = computed(() => admin.value[resources[section.value] ?? 'services'] ?? []);
const administrative = computed(() => props.data.screen === 'admin');
const rows = computed(() => (props.data[resources[section.value] ?? {solicitudes:'requests',presupuestos:'quotes',proyectos:'projects',portfolio:'works',contactos:'inquiries'}[section.value]] ?? []).filter(r => (!query.value || `${r.title ?? r.name ?? r.topic} ${r.id}`.toLowerCase().includes(query.value.toLowerCase())) && (!status.value || (r.display_status ?? r.status) === status.value)));
const quote = useForm({budget_id:selected.budget_id ?? null,request_id:selected.request_id ?? props.data.requestId ?? '',title:selected.title ?? '',currency_code:selected.currency_code ?? 'ARS',tax_rate:selected.tax_rate ?? 0,
    valid_until:selected.valid_until ?? new Date(Date.now()+14*86400000).toISOString().slice(0,10),estimated_delivery_days:selected.estimated_delivery_days ?? 30,terms:selected.terms ?? '',
    items:selected.items?.map(i=>({description:i.description,quantity:i.quantity,unit_price:i.unit_price})) ?? [{description:'',quantity:1,unit_price:''}],send:false});
const subtotal = computed(() => quote.items.reduce((sum,i)=>sum+Number(i.quantity)*Number(i.unit_price),0));
const total = computed(() => subtotal.value*(1+Number(quote.tax_rate)/100));
const work = useForm({id:selected.id ?? null,service_id:selected.service_id ?? props.data.services[0]?.database_id,title:selected.title ?? '',description:selected.description ?? '',category:selected.category ?? 'Desarrollo web',challenge:selected.challenge ?? '',result:selected.result ?? '',year:selected.year ?? new Date().getFullYear(),live_url:selected.live_url ?? '',is_public:!!selected.is_public,cover:null,gallery:[]});
const projectForm = useForm({id:null,status:'pending',completion:0,start_date:'',end_date:'',notes:''});
// completion evita colisionar con el progreso de carga interno de Inertia; al enviar se convierte a progress.
projectForm.transform(({completion,...values})=>({...values,progress:completion}));
const configuration = useForm({});
// El editor de tarifa crea una versión nueva; los importes previos quedan disponibles para consulta.
const tariff = useForm({name:'',currency_code:'ARS',active:false,services:[],components:[]});
const options = (items,label='name') => items.map(i=>({value:i.id,label:i[label]}));
// Cierra la vista previa si el servidor rechaza un dato y conserva los conceptos ingresados.
function saveQuote(send) {
    quote.send = send;
    submit(quote, 'presupuesto', {
        previewTarget: 'g-presupuestos',
        onError: () => { preview.value = false; },
    });
}
function editProject(p) { project.value=p; projectForm.defaults({id:p.id,status:p.status,completion:p.progress,start_date:p.start_date ?? '',end_date:p.end_date ?? '',notes:p.notes ?? ''}); projectForm.reset(); }
function act(action,values) { submit(useForm(values),action); }
function configure(row={}) {
    if(section.value==='tarifario') {
        tariff.name=''; tariff.currency_code=row.currency_code ?? 'ARS'; tariff.active=false;
        tariff.services=admin.value.services.filter(s=>s.active && s.estimation_mode==='automatic').map(s=>({id:s.id,name:s.name,min:row.services?.find(p=>p.service_id===s.id)?.price_min ?? '',max:row.services?.find(p=>p.service_id===s.id)?.price_max ?? ''}));
        tariff.components=admin.value.components.filter(c=>c.active).map(c=>({id:c.id,name:c.name,min:row.components?.find(p=>p.service_component_id===c.id)?.price_min ?? '',max:row.components?.find(p=>p.service_component_id===c.id)?.price_max ?? ''}));
    } else {
        const defaults={id:null,name:'',slug:'',active:true,description:'',summary:'',service_category_id:admin.value.categories[0]?.id,estimation_mode:'manual',deliverables:'',service_id:admin.value.services[0]?.id,question:'',input_type:'single_choice',sort_order:0,options_text:'',quantity_component_id:null,unit_code:'unidad',is_default:false,default_quantity:1,estimator_option_id:null,service_component_id:null,quantity:1};
        // Solo se envían los campos que el recurso permite; el servidor aplica una segunda lista explícita.
        const fields={servicios:['id','name','slug','active','description','summary','service_category_id','estimation_mode','deliverables'],preguntas:['id','service_id','question','input_type','sort_order','active','options_text','quantity_component_id'],componentes:['id','name','slug','active','description','service_id','unit_code','is_default','default_quantity'],reglas:['id','estimator_option_id','service_component_id','quantity','active']}[section.value];
        const values={...defaults,...row,active:row.active == null ? true : !!row.active,deliverables:Array.isArray(row.deliverables)?row.deliverables.join('\n'):row.deliverables ?? '',options_text:row.options?.filter(o=>o.active).map(o=>o.label).join('\n') ?? '',is_default:!!row.is_default};
        configuration.defaults(Object.fromEntries(fields.map(k=>[k,values[k]]))); configuration.reset(); configuration.clearErrors();
    }
    adminModal.value=true;
}
function saveConfiguration() { submit(section.value==='tarifario'?tariff:configuration,`/admin/guardar/${section.value}`,{onSuccess:()=>adminModal.value=false}); }
</script>
<template>
    <section v-if="data.screen === 'editor-presupuesto'" class="page shell"><B href="/gestion/presupuestos" variant="ghost">← Volver a presupuestos</B><T eyebrow="Editor de presupuesto" title="Versión formal" description="Si el presupuesto ya fue enviado, los cambios crean una versión nueva y conservan el historial." /><div v-if="Object.keys(quote.errors).length" class="notice" role="alert"><div><h2>Revisá los datos del presupuesto</h2><ul><li v-for="(error, field) in quote.errors" :key="field">{{ error }}</li></ul></div></div><form class="editor-grid" @submit.prevent="preview = true"><div class="editor-panels"><v-card class="card"><h2>Datos generales</h2><div class="form-grid"><F v-model="quote.request_id" label="Solicitud relacionada" :error="quote.errors.request_id" type="select" :disabled="!!selected.budget_id" :options="(data.budgetRequests ?? data.requests)?.filter(r=>r.status==='open').map(r=>({value:r.id,label:`SOL-${r.id} · ${r.title}`}))" required /><F v-model="quote.currency_code" label="Moneda" type="select" :options="['ARS','USD','EUR']" required /></div><F v-model="quote.title" :error="quote.errors.title" label="Título" required /></v-card><v-card class="card"><div class="section-head"><h2>Conceptos</h2><B variant="secondary" @click="quote.items.push({description:'',quantity:1,unit_price:''})">＋ Agregar</B></div><div v-for="(item,index) in quote.items" :key="index" class="budget-line"><F v-model="item.description" :label="`Concepto ${index+1}`" required /><F v-model="item.quantity" label="Cant." type="number" min="0.001" step="0.001" required /><F v-model="item.unit_price" label="Precio unitario" type="number" min="0" step="0.01" required /><button type="button" :disabled="quote.items.length===1" :aria-label="`Eliminar concepto ${index+1}`" @click="quote.items.splice(index,1)">×</button></div></v-card><v-card class="card"><h2>Condiciones</h2><div class="form-grid"><F v-model="quote.estimated_delivery_days" label="Plazo estimado (días)" type="number" min="1" required /><F v-model="quote.valid_until" label="Vigencia hasta" :error="quote.errors.valid_until" type="date" required /><F v-model="quote.tax_rate" label="Impuestos (%)" type="number" min="0" max="100" step="0.01" required /></div><F v-model="quote.terms" label="Condiciones y forma de pago" :error="quote.errors.terms" type="textarea" required /></v-card></div><aside class="card sticky"><h3>Resumen</h3><dl class="data-list"><div><dt>Subtotal</dt><dd>{{ money(subtotal,quote.currency_code) }}</dd></div><div><dt>Impuestos</dt><dd>{{ quote.tax_rate }}%</dd></div><div class="total"><dt>Total</dt><dd>{{ money(total,quote.currency_code) }}</dd></div></dl><div class="button-stack"><B type="submit">Vista previa y enviar</B><B variant="secondary" :disabled="quote.processing" @click="saveQuote(false)">Guardar borrador</B></div></aside></form><v-dialog v-model="preview" max-width="720"><div class="synaux-app"><v-card class="card modal-card"><button class="modal-close" aria-label="Cerrar" @click="preview=false">×</button><p class="eyebrow">Vista previa · Presupuesto formal</p><h2>{{ quote.title }}</h2><div v-for="(item,index) in quote.items" :key="index" class="list-row"><span>{{ item.description }} · {{ item.quantity }}</span><strong>{{ money(item.quantity*item.unit_price,quote.currency_code) }}</strong></div><h3>Total: {{ money(total,quote.currency_code) }}</h3><p>{{ quote.estimated_delivery_days }} días · Vigente hasta {{ date(quote.valid_until) }}</p><p class="preserve-lines">{{ quote.terms }}</p><div class="form-actions"><B variant="secondary" @click="preview=false">Volver a editar</B><B :disabled="quote.processing" @click="saveQuote(true)">Enviar versión formal</B></div></v-card></div></v-dialog></section>
    <!-- El portfolio se publica desde archivos raster propios y permite guardar trabajos privados. -->
    <section v-else-if="data.screen === 'editor-trabajo'" class="page shell narrow"><B href="/profesional/portfolio" variant="ghost">← Volver al portfolio</B><T eyebrow="Portfolio" :title="selected.id ? 'Editar trabajo' : 'Nuevo trabajo'" description="Documentá el desafío, la solución y el resultado del proyecto." /><v-card class="card form-card"><form @submit.prevent="submit(work,'trabajo',{forceFormData:true,previewTarget:'g-portfolio'})"><F v-model="work.title" label="Título del trabajo" required /><div class="form-grid"><F v-model="work.service_id" label="Servicio" type="select" :options="data.services.map(s=>({value:s.database_id,label:s.name}))" required /><F v-model="work.category" label="Categoría" required /><F v-model="work.year" label="Año" type="number" min="1990" max="2100" /></div><F v-model="work.description" label="Descripción breve" type="textarea" required /><F v-model="work.challenge" label="El desafío" type="textarea" /><F v-model="work.result" label="La solución y el resultado" type="textarea" /><F v-model="work.live_url" type="url" label="Enlace al proyecto (opcional)" /><img v-if="selected.cover_path" :src="selected.cover_path" :alt="selected.title" class="upload-preview"><label class="field">Imagen de portada (JPG, PNG o WebP · hasta 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" @change="work.cover=$event.target.files[0]"></label><label class="field">Galería (hasta 8 imágenes por envío)<input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="work.gallery=Array.from($event.target.files)"></label><label class="select-row"><input v-model="work.is_public" type="checkbox">Publicar este trabajo en el portfolio</label><B type="submit" :disabled="work.processing">Guardar trabajo</B></form></v-card></section>
    <!-- El administrador configura el catálogo y las preguntas sin tocar registros de clientes. -->
    <section v-else-if="administrative" class="page shell"><T eyebrow="Administración" title="Motor de estimación" description="Configuración interna del catálogo, preguntas, reglas y valores orientativos." /><div class="admin-layout"><nav class="admin-menu" aria-label="Configuración"><B v-for="[key,label] in [['servicios','Servicios'],['componentes','Componentes'],['reglas','Reglas'],['tarifario','Tarifario'],['preguntas','Preguntas']]" :key="key" :href="`/admin/${key}`" :variant="section===key?'primary':'ghost'">{{ label }}</B></nav><div><div class="section-head"><div><h2>{{ {servicios:'Servicios y categorías',preguntas:'Preguntas del estimador',componentes:'Componentes por servicio',reglas:'Reglas de cálculo',tarifario:'Versiones del tarifario'}[section] ?? 'Servicios y categorías' }}</h2><p>Los cambios se aplican a los próximos cálculos.</p></div><B @click="configure()">＋ {{ section==='tarifario'?'Nueva versión':'Agregar' }}</B></div><div class="table-scroll"><table><thead><tr><th>{{ section==='preguntas'?'Pregunta':section==='reglas'?'Opción':'Nombre' }}</th><th>Configuración</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="r in adminRows" :key="r.id"><td>{{ r.name ?? r.question ?? r.label }}</td><td>{{ r.estimation_mode === 'automatic' ? 'Automática' : r.estimation_mode === 'manual' ? 'Profesional' : r.input_type ?? (r.quantity != null ? `${r.name} × ${r.quantity}` : r.currency_code ?? r.unit_code) }}</td><td>{{ r.active ? 'Activo' : 'Inactivo' }}</td><td><B variant="ghost" @click="configure(r)">{{ section==='tarifario'?'Crear desde esta versión':'Editar' }}</B></td></tr><tr v-if="!adminRows.length"><td colspan="4">Todavía no hay registros. Agregá el primero.</td></tr></tbody></table></div><div class="notice"><div><h3>Precios y cálculos históricos</h3><p>Cada tarifario se guarda como una versión nueva. Las estimaciones y los presupuestos anteriores conservan sus valores de origen.</p></div></div></div></div>
        <v-dialog v-model="adminModal" max-width="800"><div class="synaux-app"><v-card class="card modal-card"><button class="modal-close" aria-label="Cerrar" @click="adminModal=false">×</button><h2>{{ section==='tarifario'?'Nueva versión del tarifario':'Configurar '+section }}</h2><form @submit.prevent="saveConfiguration"><template v-if="section==='tarifario'"><F v-model="tariff.name" label="Nombre de la versión" required /><F v-model="tariff.currency_code" label="Moneda" type="select" :options="['ARS','USD','EUR']" /><template v-for="[key,label] in [['services','Bases de servicios'],['components','Componentes']]" :key="key"><h3>{{ label }}</h3><div v-for="p in tariff[key]" :key="p.id" class="tariff-row"><strong>{{ p.name }}</strong><F v-model="p.min" label="Mínimo" type="number" min="0" step="0.01" required /><F v-model="p.max" label="Máximo" type="number" min="0" step="0.01" required /></div></template><label class="select-row"><input v-model="tariff.active" type="checkbox">Activar para nuevas estimaciones</label><p>Completá las bases y todos los componentes de los servicios automáticos para activar la versión.</p></template><template v-else><template v-if="['servicios','componentes'].includes(section)"><F v-model="configuration.name" label="Nombre" required /><F v-model="configuration.slug" label="Identificador (sin espacios)" required /><F v-model="configuration.description" type="textarea" label="Descripción" required /></template><template v-if="section==='servicios'"><F v-model="configuration.service_category_id" type="select" label="Categoría" :options="options(admin.categories)" required /><F v-model="configuration.summary" label="Resumen para el catálogo" required /><F v-model="configuration.estimation_mode" type="select" label="Tipo de estimación" :options="[{value:'manual',label:'Revisión profesional'},{value:'automatic',label:'Automática'}]" required /><F v-model="configuration.deliverables" type="textarea" label="Entregables (uno por línea)" required /></template><template v-if="['preguntas','componentes'].includes(section)"><F v-model="configuration.service_id" type="select" label="Servicio" :options="options(admin.services)" :required="section==='componentes'" /></template><template v-if="section==='preguntas'"><F v-model="configuration.question" label="Pregunta" required /><F v-model="configuration.input_type" label="Tipo de respuesta" type="select" :options="[{value:'single_choice',label:'Una opción'},{value:'multiple_choice',label:'Varias opciones'},{value:'number',label:'Cantidad'},{value:'text',label:'Texto'}]" required /><F v-model="configuration.sort_order" label="Orden" type="number" min="0" required /><F v-if="configuration.input_type.includes('choice')" v-model="configuration.options_text" type="textarea" label="Opciones (una por línea)" required /><F v-if="configuration.input_type==='number'" v-model="configuration.quantity_component_id" type="select" label="Componente cuya cantidad define" :options="options(admin.components.filter(c=>c.service_id==configuration.service_id))" /></template><template v-if="section==='componentes'"><F v-model="configuration.unit_code" label="Unidad" required /><F v-model="configuration.default_quantity" label="Cantidad inicial" type="number" min="0.001" step="0.001" required /><label class="select-row"><input v-model="configuration.is_default" type="checkbox">Incluir por defecto</label></template><template v-if="section==='reglas'"><F v-model="configuration.estimator_option_id" type="select" label="Opción de respuesta" :options="admin.questions.flatMap(q=>q.options.filter(o=>o.active).map(o=>({value:o.id,label:`${q.question}: ${o.label}`})))" required /><F v-model="configuration.service_component_id" type="select" label="Componente" :options="options(admin.components)" required /><F v-model="configuration.quantity" type="number" label="Cantidad que incorpora" min="0" step="0.001" required /></template><label class="select-row"><input v-model="configuration.active" type="checkbox">Activo</label></template><div class="form-actions"><B variant="secondary" @click="adminModal=false">Cancelar</B><B type="submit" :disabled="configuration.processing || tariff.processing">Guardar</B></div></form></v-card></div></v-dialog>
    </section>
    <section v-else class="page shell"><T :eyebrow="data.screen==='profesional'?'Área profesional':'Gestión Synaux'" :title="section==='resumen'?'Resumen de gestión':{solicitudes:'Solicitudes recibidas',presupuestos:'Presupuestos',proyectos:'Seguimiento de proyectos',portfolio:'Portfolio',contactos:'Consultas recibidas'}[section]" description="Seguí cada proyecto desde la primera solicitud hasta la entrega."><B v-if="section==='portfolio'" href="/editor/trabajo" arrow>Nuevo trabajo</B><B v-if="section==='presupuestos'" href="/editor/presupuesto" arrow>Nuevo presupuesto</B></T><template v-if="section==='resumen'"><div class="stats-grid"><v-card v-for="[label,key] in [['Solicitudes abiertas','requests'],['Presupuestos','quotes'],['Proyectos activos','projects'],['Consultas','inquiries']]" :key="key" class="card stat"><span>{{ label }}</span><strong>{{ data[key]?.length ?? 0 }}</strong></v-card></div><v-card class="card"><h2>Solicitudes por revisar</h2><div v-for="r in data.requests?.filter(r=>r.status==='open').slice(0,5)" :key="r.id" class="list-row"><div><h3>{{ r.title }}</h3><small>SOL-{{ r.id }} · {{ date(r.created_at) }}</small></div><B :href="`/solicitudes/${r.id}`" variant="secondary">Revisar solicitud</B></div><B href="/gestion/contactos" variant="ghost">Consultar mensajes de contacto →</B></v-card></template><template v-else><div class="filters"><F v-model="query" label="Buscar" placeholder="Nombre o identificador" /><F v-if="section!=='portfolio' && section!=='contactos'" v-model="status" label="Estado" type="select" :options="[{value:'',label:'Todos'},{value:'open',label:'Enviada'},{value:'draft',label:'Borrador'},{value:'sent',label:'Enviado'},{value:'accepted',label:'Aceptado'},{value:'pending',label:'Pendiente'},{value:'in_progress',label:'En curso'},{value:'completed',label:'Completado'}]" /></div><div class="stack"><v-card v-for="r in rows" :key="r.id" class="card list-row"><div><small>{{ date(r.created_at) }}</small><h3>{{ r.title ?? r.topic }}</h3><S v-if="r.status" :status="r.display_status ?? r.status" /><p v-if="section==='contactos'">{{ r.name }} · {{ r.email }}</p><p v-if="section==='contactos'" class="preserve-lines">{{ r.message }}</p><p v-if="section==='presupuestos'">Versión {{ r.version_number }} · {{ money(r.total,r.currency_code) }}</p><p v-if="section==='portfolio'">{{ r.is_public ? 'Publicado' : 'Privado' }} · {{ r.category }}</p><progress v-if="section==='proyectos'" max="100" :value="r.progress" /></div><div class="button-row"><template v-if="section==='solicitudes'"><B :href="`/solicitudes/${r.id}`" variant="secondary">Ver detalle</B><B v-if="r.status==='open'" :href="`/editor/presupuesto?solicitud=${r.id}`">Preparar presupuesto</B><B v-if="r.status==='open' && !r.reviewed_at" variant="ghost" @click="act('estado-solicitud',{id:r.id,status:'review'})">Marcar revisada</B></template><template v-if="section==='presupuestos'"><B :href="`/presupuestos/${r.id}`" variant="secondary">Ver versión</B><B :href="`/editor/presupuesto/${r.id}`">Editar / nueva versión</B></template><B v-if="section==='proyectos'" @click="editProject(r)">Actualizar avance</B><B v-if="section==='portfolio'" :href="`/editor/trabajo/${r.id}`" variant="secondary">Editar trabajo</B></div></v-card></div><E v-if="!rows.length" title="No hay registros para mostrar" text="La actividad del proyecto aparecerá en esta sección." /></template><v-dialog :model-value="!!project" max-width="650" @update:model-value="project=$event?project:null"><div class="synaux-app"><v-card class="card modal-card"><h2>{{ project?.title }}</h2><form @submit.prevent="submit(projectForm,'proyecto',{onSuccess:()=>project=null})"><F v-model="projectForm.status" label="Estado" type="select" :options="[{value:'pending',label:'Pendiente'},{value:'in_progress',label:'En curso'},{value:'completed',label:'Completado'},{value:'cancelled',label:'Cancelado'}]" /><F v-model="projectForm.completion" label="Avance (%)" type="number" min="0" max="100" /><div class="form-grid"><F v-model="projectForm.start_date" label="Fecha de inicio" type="date" /><F v-model="projectForm.end_date" label="Fecha de cierre" type="date" /></div><F v-model="projectForm.notes" label="Actualización y próximos pasos" type="textarea" /><div class="form-actions"><B variant="secondary" @click="project=null">Volver</B><B type="submit" :disabled="projectForm.processing">Guardar avance</B></div></form></v-card></div></v-dialog></section>
</template>


